#if DEBUG
import SwiftUI
import SwiftData

/// Deterministic, local-only Discover surface for UI tests and previews. Never loads
/// an account, never syncs. Launch with `--discover-ui-test` (add `--discover-offline`
/// for the no-cache state). The fixture is real Open Library records captured once,
/// standing in for every collection; it is not chart or NYT data.
struct DiscoverTestHarness: View {
    @State private var setup = try? DiscoverHarnessSetup()

    var body: some View {
        if let setup {
            DiscoverView(repository: setup.library)
                .modelContainer(setup.container)
                .environment(\.discoveryRepository, setup.discovery)
                .environment(\.reviewLibraryRepository, setup.library)
                .textualScreenDefaults()
        } else {
            Text("Harness unavailable")
        }
    }
}

@MainActor
private final class DiscoverHarnessSetup {
    let container: ModelContainer
    let library: LibraryRepository
    let discovery: DiscoveryRepository

    init() throws {
        let schema = Schema([Book.self, Tag.self, LibrarySyncState.self, ReaderProfileDraft.self, ReaderReviewDraft.self,
                             DiscoveryCacheEntry.self, DiscoveryCollectionState.self])
        container = try ModelContainer(for: schema, configurations: ModelConfiguration(schema: schema, isStoredInMemoryOnly: true))
        let user = UUID(uuidString: "00000000-0000-0000-0000-00000000D15C")!
        library = LibraryRepository(userID: user, modelContext: container.mainContext, transport: HarnessLibraryTransport(userID: user))
        let offline = ProcessInfo.processInfo.arguments.contains("--discover-offline")
        discovery = DiscoveryRepository(context: container.mainContext, transport: HarnessDiscoveryTransport(offline: offline))
    }
}

private struct HarnessLibraryTransport: LibrarySyncTransport {
    let userID: UUID
    func authenticatedUserID() async throws -> UUID { userID }
    func synchronize(_ request: LibrarySyncRequest) async throws -> LibrarySyncResponse { throw URLError(.notConnectedToInternet) }
}

private struct HarnessDiscoveryTransport: DiscoveryTransport {
    let offline: Bool
    func page(_ collection: DiscoveryCollection, offset: Int, limit: Int) async throws -> DiscoveryPage {
        if offline { throw URLError(.notConnectedToInternet) }
        try await Task.sleep(for: .milliseconds(300))
        let all = try JSONSerialization.jsonObject(with: Data(Self.fixture.utf8)) as? [String: Any]
        let rows = (all?[collection.rawValue] as? [Any]) ?? []
        let page: [String: Any] = ["collection": collection.rawValue, "refreshed_at": "2026-10-12T10:00:00+00:00",
                                   "total": rows.count, "attribution": [],
                                   "books": Array(rows.dropFirst(offset).prefix(limit))]
        return try JSONDecoder().decode(DiscoveryPage.self, from: JSONSerialization.data(withJSONObject: page))
    }

